  const movePopularCategory = (index: number, direction: -1 | 1) => setPopularCategoryIds(current => { const target = index + direction; if (target < 0 || target >= current.length) return current; const next = [...current]; [next[index], next[target]] = [next[target], next[index]]; return next; });
